            throw Core.StreamFailure("CDLADVANCEBLOCK", "update", RetCode.BadParam);
         }
         core.CdladvanceblockStepImpl(this, inOpen, inHigh, inLow, inClose);
         if( outRangeCount < Core.MAX_INDEX ) outRangeCount++;
